SELECT  FROM notes
WHERE user_id = #{userId}
ORDER BY is_pinned DESC, updated_at DESC

SELECT  FROM notes
WHERE user_id = #{userId} AND folder_id = #{folderId}
ORDER BY is_pinned DESC, updated_at DESC

SELECT  FROM notes
WHERE user_id = #{userId}
ORDER BY updated_at DESC
LIMIT #{limit}

SELECT  FROM notes
WHERE user_id = #{userId} AND title = #{title}
LIMIT 1
